#include <bits/extc++.h>

using namespace std;

// 隣接する頂点の情報を受け取る
vector<unsigned> read_vector() {
    unsigned k;
    cin >> k;
    vector<unsigned> ret(k);
    for (auto &&r : ret)
        cin >> r;
    return ret;
}

int main() {
    using namespace std;
    unsigned long N, M;
    cin >> N >> M;

    // dfs を行う関数
    [dfs{[N, visited{vector<unsigned long>(N + 1)}](auto &&f, unsigned now, unsigned prev) mutable -> void {
        // N に到達したら、終了
        if (now == N) {
            string S;
            cin >> S;
            exit(0);
        }

        // 訪れたことを記録
        visited[now] = 1;

        // 隣接している頂点それぞれについて
        for (const auto next : read_vector())
            if (!visited[next]) {
                // 訪れたことがないならそこへ移動
                cout << next << endl;
                f(f, next, now);
            }

        // まわりに未探索の頂点がなくなったら、親に戻る
        cout << prev << endl;
        read_vector();
    }}]() mutable {
        // はじめは頂点 1 から
        dfs(dfs, 1, 1);
    }();
    return 0;
}
